    "texts": [
      {
        "id": "L25-T1",
        "title": "いろいろお世話になりました",
        "subtitle": "会話",
        "lines": [
          {
            "speaker": "木村",
            "ja": "転勤、おめでとうございます。",
            "zh": "恭喜调动工作。"
          },
          {
            "speaker": "ミラー",
            "ja": "ありがとうございます。",
            "zh": "谢谢。"
          },
          {
            "speaker": "木村",
            "ja": "ミラーさんが東京へ行ったら、寂しくなりますね。",
            "zh": "米勒先生去了东京后，会变得寂寞呢。"
          },
          {
            "speaker": "佐藤",
            "ja": "そうですね。",
            "zh": "是啊。"
          },
          {
            "speaker": "木村",
            "ja": "東京へ行っても、大阪のことを忘れないでくださいね。",
            "zh": "即使去了东京，也请不要忘记大阪哦。"
          },
          {
            "speaker": "ミラー",
            "ja": "もちろん。皆さん、暇があったら、ぜひ東京へ遊びに来てください。",
            "zh": "当然。大家有空的话，请一定来东京玩。"
          },
          {
            "speaker": "サントス",
            "ja": "ミラーさんも大阪へ来たら、電話をください。いっしょに飲みましょう。",
            "zh": "米勒先生来大阪的话，也请给我打电话。一起喝一杯吧。"
          },
          {
            "speaker": "ミラー",
            "ja": "ええ、ぜひ。皆さん、ほんとうにいろいろお世話になりました。",
            "zh": "好的，一定。各位，真的承蒙大家多方照顾。"
          },
          {
            "speaker": "佐藤",
            "ja": "頑張ってください。お体に気をつけて。",
            "zh": "请加油。请注意身体。"
          },
          {
            "speaker": "ミラー",
            "ja": "はい。皆さんもどうぞお元気で。",
            "zh": "好的。大家也请多保重。"
          }
        ]
      }
    ]
